package com.cryptostrategy.platform.persistence.evaluation;
import static org.junit.jupiter.api.Assertions.*;import com.cryptostrategy.platform.evaluation.api.model.*;import com.cryptostrategy.platform.evaluation.internal.DeterministicEvaluator;import com.cryptostrategy.platform.persistence.api.*;import com.cryptostrategy.platform.persistence.support.F006DatabaseFixture;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;
class JdbcEvaluationResultStoreIntegrationTest{@Test void persistsOneImmutableMetricAndRankingVersionForSameExperiment(){var source=F006DatabaseFixture.dataSource();F006DatabaseFixture.transaction(source).executeWithoutResult(status->{status.setRollbackOnly();var jdbc=new JdbcTemplate(source);F006DatabaseFixture.seed(jdbc);var result=F006DatabaseFixture.result();new BacktestingPersistenceFactory(source).createResultStore().save(result);var evaluation=new DeterministicEvaluator().evaluate(result,new MetricVersion("metrics-v1"),new RankingVersion("ranking-v1"));var store=new EvaluationPersistenceFactory(source).createStore();store.save(evaluation);store.save(evaluation);assertEquals(1,jdbc.queryForObject("select count(*) from experiment.evaluation_result where backtest_result_id=?",Integer.class,result.resultId().value()));assertThrows(Exception.class,()->jdbc.update("update experiment.evaluation_result set overall_score=0 where evaluation_result_id=?",evaluation.evaluationResultId().value()));});}}
